import { useState, useEffect, useCallback } from "react";
import { Helmet } from "react-helmet-async";
import { FileText, Sparkles, Youtube, ExternalLink, PlayCircle, Loader2, Clock, RefreshCw } from "lucide-react";
import { Sidebar } from "@/components/Sidebar";
import { UrlInput } from "@/components/UrlInput";
import { VideoPreview } from "@/components/VideoPreview";
import { NotesDisplay } from "@/components/NotesDisplay";
import { useYoutubeNotes } from "@/hooks/useYoutubeNotes";
import { ThemeToggle } from "@/components/ThemeToggle";

interface Recommendation {
  query: string;
  videoId?: string;
  title?: string;
  thumbnail?: string;
  channel?: string;
}

const Index = () => {
  const [recommendations, setRecommendations] = useState<Recommendation[]>([]);
  const [isLoadingRecs, setIsLoadingRecs] = useState(false);
  const [historyTrigger, setHistoryTrigger] = useState(0);
  const {
    isLoadingVideo,
    isLoadingNotes,
    videoInfo,
    notes,
    processVideo,
    setVideoInfo,
    setNotes,
    reset,
  } = useYoutubeNotes();

  const fetchRecs = useCallback(async () => {
    if (!notes || !videoInfo?.title) return;

    setIsLoadingRecs(true);
    try {
      const res = await fetch('http://localhost:3001/api/recommendations', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ videoTitle: videoInfo.title, notes })
      });
      const data = await res.json();
      if (data.recommendations) {
        setRecommendations(data.recommendations);
      }
    } catch (e) {
      console.error("Failed to fetch recs", e);
    } finally {
      setIsLoadingRecs(false);
    }
  }, [notes, videoInfo?.title]);

  useEffect(() => {
    if (notes && videoInfo?.title) {
      fetchRecs();
    } else {
      setRecommendations([]);
    }
  }, [fetchRecs, notes, videoInfo?.title]);

  const handleSubmit = async (url: string, manualTranscript?: string) => {
    await processVideo(url, manualTranscript);
    setHistoryTrigger(prev => prev + 1);
  };

  const handleHistorySelect = (item: any) => {
    setVideoInfo({
      id: item.videoId,
      title: item.title,
      channelTitle: "",
      thumbnail: item.thumbnail,
      description: "",
    });
    setNotes(item.notes);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <>
      <Helmet>
        <title>NoteTube - AI Note Generator</title>
        <meta
          name="description"
          content="Transform YouTube videos into beginner-friendly study notes with AI."
        />
      </Helmet>

      <div className="min-h-screen bg-background font-sans selection:bg-primary/20 relative">
        <Sidebar onHistorySelect={handleHistorySelect} refreshTrigger={historyTrigger} onNewNote={reset} />

        {/* Theme Toggle - Fixed Top Right */}
        <div className="fixed top-4 right-4 z-50">
          <ThemeToggle />
        </div>

        <main className="lg:pl-[320px]">
          {(!videoInfo && !notes && !isLoadingVideo && !isLoadingNotes) ? (
            <div className="relative min-h-screen flex items-center justify-center overflow-hidden p-6 lg:p-12">
              {/* Aurora Background */}
              <div className="absolute top-[-20%] right-[-10%] w-[600px] h-[600px] bg-primary/20 rounded-full blur-[120px] mix-blend-screen animate-pulse-glow" />
              <div className="absolute bottom-[-10%] left-[-10%] w-[500px] h-[500px] bg-blue-500/10 rounded-full blur-[100px] mix-blend-screen" />

              <div className="container relative z-10 w-full max-w-7xl mx-auto">
                <div className="grid lg:grid-cols-2 gap-12 lg:gap-20 items-center">

                  {/* Left Column: Content */}
                  <div className="flex flex-col items-start text-left space-y-8 animate-fade-in">
                    <div className="inline-flex items-center px-3 py-1 rounded-full bg-white/5 border border-white/10 text-xs font-medium text-primary backdrop-blur-sm">
                      <Sparkles className="w-3.5 h-3.5 mr-2 fill-primary" />
                      <span>The Second Brain for YouTube</span>
                    </div>

                    <h1 className="text-6xl lg:text-8xl font-black tracking-tighter leading-[0.9] text-foreground">
                      Learn <br />
                      <span className="text-transparent bg-clip-text bg-gradient-to-r from-primary via-indigo-400 to-cyan-400">
                        Faster.
                      </span>
                    </h1>

                    <p className="text-xl text-muted-foreground/80 leading-relaxed max-w-lg font-light">
                      Stop scrubbing through hours of video. Get instant, structured notes, summaries, and chat with any YouTube video.
                    </p>

                    <div className="w-full max-w-md pt-4">
                      <div className="ring-1 ring-white/10 p-1 rounded-2xl bg-black/5 backdrop-blur-sm">
                        <UrlInput onSubmit={handleSubmit} isLoading={isLoadingVideo || isLoadingNotes} />
                      </div>
                      <div className="flex items-center gap-4 mt-6 text-sm font-medium">
                        <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-primary/10 text-primary border border-primary/10 transition-transform hover:scale-105 cursor-default">
                          <Clock className="w-4 h-4 fill-primary/20" />
                          <span>60s Processing</span>
                        </span>
                        <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-purple-500/10 text-purple-400 border border-purple-500/10 transition-transform hover:scale-105 cursor-default">
                          <FileText className="w-4 h-4 fill-purple-500/20" />
                          <span>PDF Export</span>
                        </span>
                        <span className="flex items-center gap-2 px-3 py-1.5 rounded-full bg-cyan-500/10 text-cyan-400 border border-cyan-500/10 transition-transform hover:scale-105 cursor-default">
                          <Sparkles className="w-4 h-4 fill-cyan-500/20" />
                          <span>AI Chat</span>
                        </span>
                      </div>
                    </div>
                  </div>

                  {/* Right Column: Dynamic Visuals */}
                  <div className="relative hidden lg:block h-[600px] perspective-[2000px]">
                    {/* Floating Card 1: The Video */}
                    <div className="absolute top-[10%] right-[10%] w-[320px] bg-card/80 backdrop-blur-xl border border-white/10 p-3 rounded-2xl shadow-2xl transform rotate-[-6deg] translate-z-[50px] animate-float-slow">
                      <div className="w-full aspect-video bg-black/40 rounded-lg mb-3 overflow-hidden relative">
                        <div className="relative w-full h-full group">
                          <div className="absolute inset-0 bg-primary/20 mix-blend-overlay z-10" />
                          <img
                            src="https://images.unsplash.com/photo-1611162616475-46b635cb6868?q=80&w=1000&auto=format&fit=crop"
                            alt="YouTube Content"
                            className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110"
                          />
                          <div className="absolute inset-0 flex items-center justify-center z-20 opacity-90">
                            <div className="w-12 h-12 bg-white/20 backdrop-blur-md rounded-full flex items-center justify-center border border-white/30 shadow-xl">
                              <div className="w-0 h-0 border-t-[6px] border-t-transparent border-l-[10px] border-l-white border-b-[6px] border-b-transparent ml-1" />
                            </div>
                          </div>
                        </div>
                      </div>
                      <div className="h-2 w-3/4 bg-white/10 rounded-full mb-2" />
                      <div className="h-2 w-1/2 bg-white/10 rounded-full" />
                    </div>

                    {/* Floating Card 2: The Notes */}
                    <div className="absolute top-[30%] left-[10%] w-[380px] bg-white/5 backdrop-blur-2xl border border-white/20 p-6 rounded-2xl shadow-2xl transform rotate-[3deg] translate-z-[100px] animate-float-delayed z-10">
                      <div className="flex items-center gap-3 mb-6 border-b border-white/5 pb-4">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-primary to-purple-500" />
                        <div className="space-y-1">
                          <div className="h-2 w-24 bg-white/20 rounded-full" />
                          <div className="h-1.5 w-16 bg-white/10 rounded-full" />
                        </div>
                      </div>
                      <div className="space-y-4">
                        <div className="h-3 w-full bg-white/10 rounded-full" />
                        <div className="h-3 w-[90%] bg-white/10 rounded-full" />
                        <div className="h-3 w-[95%] bg-white/10 rounded-full" />
                        <div className="flex gap-2 mt-4">
                          <div className="h-20 w-1/3 bg-primary/10 rounded-lg border border-primary/20" />
                          <div className="h-20 w-1/3 bg-purple-500/10 rounded-lg border border-purple-500/20" />
                          <div className="h-20 w-1/3 bg-blue-500/10 rounded-lg border border-blue-500/20" />
                        </div>
                      </div>
                    </div>

                    {/* Floating Card 3: Chat/AI */}
                    <div className="absolute bottom-[10%] right-[20%] w-[280px] bg-black/40 backdrop-blur-xl border border-white/10 p-4 rounded-2xl shadow-xl transform rotate-[-3deg] translate-z-[20px] animate-float z-0">
                      <div className="flex items-start gap-3">
                        <div className="w-8 h-8 rounded-full bg-indigo-500 flex items-center justify-center text-[10px] text-white font-bold">AI</div>
                        <div className="bg-white/10 rounded-r-xl rounded-bl-xl p-3 text-sm text-white/80 leading-snug">
                          Here's a summary of the key concepts from the video...
                        </div>
                      </div>
                    </div>
                  </div>

                </div>
              </div>
            </div>
          ) : (
            /* Dashboard layout filling the screen */
            <div className="h-screen p-4 lg:p-6 overflow-hidden flex flex-col">
              <div className="grid lg:grid-cols-12 gap-6 h-full">
                {/* Video Column */}
                <div className="lg:col-span-4 flex flex-col gap-6 h-full min-h-0">
                  <div className="glass-card p-1 rounded-xl overflow-hidden bg-white/5 border-white/10 shadow-xl shrink-0">
                    <VideoPreview video={videoInfo} isLoading={isLoadingVideo} />
                  </div>

                  {/* Related Topics Widget */}
                  <div className="glass-card rounded-xl p-4 bg-white/5 border-white/10 flex-1 min-h-0 flex flex-col animate-scale-in shadow-lg">
                    <div className="flex items-center justify-between mb-4 px-1">
                      <h3 className="text-xs font-bold uppercase tracking-widest text-muted-foreground/50 flex items-center gap-2">
                        <Sparkles className="w-3 h-3" />
                        Related Content
                      </h3>
                      {recommendations.length > 0 && (
                        <button
                          onClick={fetchRecs}
                          disabled={isLoadingRecs}
                          className="text-muted-foreground/50 hover:text-primary transition-colors p-1 rounded-md hover:bg-white/5 active:scale-95 disabled:opacity-50"
                          title="Refresh Suggestions"
                        >
                          <RefreshCw className={`w-3 h-3 ${isLoadingRecs ? 'animate-spin' : ''}`} />
                        </button>
                      )}
                    </div>
                    <div className="space-y-2 overflow-y-auto px-1 -mr-2 pr-2 custom-scrollbar">
                      {isLoadingRecs ? (
                        <div className="flex flex-col items-center justify-center h-full text-muted-foreground py-8">
                          <Loader2 className="w-6 h-6 animate-spin mb-2 opacity-50" />
                          <span className="text-xs">Curating resources...</span>
                        </div>
                      ) : recommendations.length > 0 ? (
                        <div className="space-y-3">
                          {recommendations.map((rec, idx) => (
                            <button
                              key={idx}
                              onClick={async () => {
                                if (rec.videoId) {
                                  window.scrollTo({ top: 0, behavior: 'smooth' });
                                  await processVideo(`https://www.youtube.com/watch?v=${rec.videoId}`);
                                  setHistoryTrigger(prev => prev + 1);
                                } else {
                                  window.open(`https://www.youtube.com/results?search_query=${encodeURIComponent(rec.query)}`, '_blank');
                                }
                              }}
                              className="block w-full text-left group p-2.5 rounded-xl hover:bg-white/5 transition-all border border-white/5 hover:border-primary/30 active:scale-[0.98] bg-black/20 hover:shadow-lg hover:shadow-primary/5"
                            >
                              <div className="flex items-start gap-4">
                                <div className="relative w-28 aspect-video rounded-lg overflow-hidden bg-black/40 shrink-0 border border-white/10 group-hover:border-primary/40 transition-all duration-300 shadow-sm">
                                  {(rec.thumbnail || rec.videoId) ? (
                                    <img
                                      src={rec.thumbnail || (rec.videoId ? `https://i.ytimg.com/vi/${rec.videoId}/hqdefault.jpg` : '')}
                                      alt=""
                                      className="object-cover w-full h-full opacity-70 group-hover:opacity-100 group-hover:scale-110 transition-all duration-500"
                                    />
                                  ) : (
                                    <div className="w-full h-full flex items-center justify-center bg-white/5">
                                      <PlayCircle className="w-8 h-8 text-muted-foreground/30" />
                                    </div>
                                  )}

                                  {/* Play Icon Overlay */}
                                  {rec.videoId && (
                                    <div className="absolute inset-0 flex items-center justify-center bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                                      <div className="w-10 h-10 rounded-full bg-primary/20 backdrop-blur-md flex items-center justify-center border border-white/20 shadow-xl">
                                        <PlayCircle className="w-6 h-6 text-white" />
                                      </div>
                                    </div>
                                  )}

                                  {/* Generate Notes Badge */}
                                  {rec.videoId && (
                                    <div className="absolute top-1 right-1 px-1.5 py-0.5 rounded backdrop-blur-md bg-black/60 border border-white/10 text-[9px] font-bold text-primary opacity-0 group-hover:opacity-100 transition-opacity duration-300 uppercase tracking-tighter">
                                      AI Notes
                                    </div>
                                  )}
                                </div>
                                <div className="flex-1 min-w-0 pt-0.5">
                                  <p className="font-semibold text-xs leading-[1.4] text-foreground/80 group-hover:text-primary transition-colors line-clamp-2 mb-1.5">
                                    {rec.title || rec.query}
                                  </p>
                                  <div className="flex flex-col gap-1">
                                    {rec.channel && (
                                      <p className="text-[10px] text-muted-foreground/60 truncate flex items-center gap-1">
                                        <Youtube className="w-3 h-3 text-red-500/60" />
                                        {rec.channel}
                                      </p>
                                    )}
                                    {!rec.channel && (
                                      <p className="text-[10px] text-muted-foreground/40 italic">Search Topic</p>
                                    )}

                                    {rec.videoId ? (
                                      <div className="flex items-center gap-1 text-[10px] text-primary/70 font-medium mt-1 opacity-0 group-hover:opacity-100 transform translate-x-[-10px] group-hover:translate-x-0 transition-all duration-300">
                                        <span>Click to process</span>
                                        <Sparkles className="w-2.5 h-2.5" />
                                      </div>
                                    ) : (
                                      <div className="flex items-center gap-1 text-[10px] text-muted-foreground/50 font-medium mt-1 opacity-0 group-hover:opacity-100 transform translate-x-[-10px] group-hover:translate-x-0 transition-all duration-300">
                                        <span>Search on YouTube</span>
                                        <ExternalLink className="w-2.5 h-2.5" />
                                      </div>
                                    )}
                                  </div>
                                </div>
                              </div>
                            </button>
                          ))}
                        </div>
                      ) : (
                        <div className="p-8 text-center text-muted-foreground/50 text-sm flex flex-col items-center gap-2">
                          <Youtube className="w-8 h-8 opacity-20" />
                          <p>Generate notes to see related study topics.</p>
                        </div>
                      )}
                    </div>
                  </div>
                </div>

                {/* Notes Column - Full Height */}
                <div className="lg:col-span-8 h-full min-h-0">
                  {notes ? (
                    <NotesDisplay
                      notes={notes}
                      isLoading={isLoadingNotes}
                      videoTitle={videoInfo?.title}
                    />
                  ) : (
                    <div className="h-full flex items-center justify-center glass-card rounded-xl">
                      <NotesDisplay notes="" isLoading={true} />
                    </div>
                  )}
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </>
  );
};

export default Index;
